import os, re
def imports(m):
    p = m.replace('.', '/') + '.lean'
    return re.findall(r'^import\s+(AlgebraicJacobian[\w.]*)', open(p).read(), re.M) if os.path.exists(p) else []
seen, stack = set(), ['AlgebraicJacobian']
while stack:
    m = stack.pop()
    if m not in seen:
        seen.add(m); stack += imports(m)
disk=set()
for r,_,fs in os.walk('AlgebraicJacobian'):
    for f in fs:
        if f.endswith('.lean'):
            disk.add(os.path.join(r,f)[:-5].replace('/','.'))
print("on disk:",len(disk),"rooted-reachable:",len(seen & disk))
print("UNROOTED:")
for m in sorted(disk-seen): print("  ",m)
# headline
seen2, stack2 = set(), ['AlgebraicJacobian.Jacobian']
while stack2:
